namespace Calc;

/// <summary>Overflow- and zero-checked 64-bit binary operations.</summary>
internal static class Arithmetic
{
    public static bool TryApply(byte op, long lhs, long rhs, out long result)
    {
        result = 0;
        try
        {
            switch (op)
            {
                case (byte)'+':
                    result = checked(lhs + rhs);
                    return true;
                case (byte)'-':
                    result = checked(lhs - rhs);
                    return true;
                case (byte)'*':
                    result = checked(lhs * rhs);
                    return true;
                case (byte)'/':
                    if (rhs == 0 || (lhs == long.MinValue && rhs == -1))
                    {
                        return false;
                    }

                    result = lhs / rhs;
                    return true;
                case (byte)'%':
                    if (rhs == 0)
                    {
                        return false;
                    }

                    // long.MinValue % -1 throws in .NET, but mathematically the remainder is 0.
                    result = rhs == -1 ? 0 : lhs % rhs;
                    return true;
                default:
                    throw new ArgumentOutOfRangeException(nameof(op), op, "Unknown operator.");
            }
        }
        catch (OverflowException)
        {
            return false;
        }
    }
}

namespace Calc;

/// <summary>
/// Recursive-descent evaluator for signed 64-bit integer expressions:
/// <code>
/// expr    := term    (('+' | '-') term)*
/// term    := unary   (('*' | '/' | '%') unary)*
/// unary   := '-' unary | primary
/// primary := NUMBER | '(' expr ')'
/// </code>
/// Any syntax error, division by zero or overflow makes evaluation fail.
/// </summary>
internal ref struct Evaluator
{
    private readonly ReadOnlySpan<byte> _text;
    private int _pos;

    private Evaluator(ReadOnlySpan<byte> text)
    {
        _text = text;
        _pos = 0;
    }

    public static bool TryEvaluate(ReadOnlySpan<byte> text, out long value)
    {
        var evaluator = new Evaluator(text);
        if (!evaluator.TryExpr(out value))
        {
            return false;
        }

        evaluator.SkipWhitespace();
        return evaluator._pos == text.Length;
    }

    private bool TryExpr(out long value)
    {
        if (!TryTerm(out value))
        {
            return false;
        }

        while (true)
        {
            byte op = Peek();
            if (op is not ((byte)'+' or (byte)'-'))
            {
                return true;
            }

            _pos++;
            if (!TryTerm(out long rhs) || !Arithmetic.TryApply(op, value, rhs, out value))
            {
                return false;
            }
        }
    }

    private bool TryTerm(out long value)
    {
        if (!TryUnary(out value))
        {
            return false;
        }

        while (true)
        {
            byte op = Peek();
            if (op is not ((byte)'*' or (byte)'/' or (byte)'%'))
            {
                return true;
            }

            _pos++;
            if (!TryUnary(out long rhs) || !Arithmetic.TryApply(op, value, rhs, out value))
            {
                return false;
            }
        }
    }

    private bool TryUnary(out long value)
    {
        if (Peek() == (byte)'-')
        {
            _pos++;
            if (!TryUnary(out long operand) || operand == long.MinValue)
            {
                value = 0;
                return false;
            }

            value = -operand;
            return true;
        }

        return TryPrimary(out value);
    }

    private bool TryPrimary(out long value)
    {
        value = 0;
        byte next = Peek();

        if (next == (byte)'(')
        {
            _pos++;
            if (!TryExpr(out value) || Peek() != (byte)')')
            {
                return false;
            }

            _pos++;
            return true;
        }

        return char.IsAsciiDigit((char)next) && TryNumber(out value);
    }

    private bool TryNumber(out long value)
    {
        value = 0;
        while (_pos < _text.Length && char.IsAsciiDigit((char)_text[_pos]))
        {
            int digit = _text[_pos++] - '0';
            if (value > (long.MaxValue - digit) / 10)
            {
                return false;
            }

            value = (value * 10) + digit;
        }

        return true;
    }

    /// <summary>Skips whitespace and returns the next byte without consuming it, or 0 at end of input.</summary>
    private byte Peek()
    {
        SkipWhitespace();
        return _pos < _text.Length ? _text[_pos] : (byte)0;
    }

    private void SkipWhitespace()
    {
        while (_pos < _text.Length && _text[_pos] is (byte)' ' or (byte)'\t')
        {
            _pos++;
        }
    }
}

using System.Buffers;
using System.Globalization;
using System.Text;

namespace Calc;

/// <summary>Reads newline-separated expressions and writes one result per non-blank line.</summary>
internal static class LineProcessor
{
    private static readonly byte[] ErrorBytes = "error\n"u8.ToArray();

    public static void Process(Stream input, Stream output)
    {
        ArgumentNullException.ThrowIfNull(input);
        ArgumentNullException.ThrowIfNull(output);

        byte[] data = ReadAll(input);
        using var writer = new BufferedStream(output, 1 << 16);
        Span<byte> number = stackalloc byte[24];

        ReadOnlySpan<byte> remaining = data;
        while (!remaining.IsEmpty)
        {
            int newline = remaining.IndexOf((byte)'\n');
            ReadOnlySpan<byte> line = newline < 0 ? remaining : remaining[..newline];
            remaining = newline < 0 ? [] : remaining[(newline + 1)..];

            if (IsBlank(line))
            {
                continue;
            }

            if (Evaluator.TryEvaluate(line, out long value)
                && value.TryFormat(number, out int written, provider: CultureInfo.InvariantCulture))
            {
                number[written++] = (byte)'\n';
                writer.Write(number[..written]);
            }
            else
            {
                writer.Write(ErrorBytes);
            }
        }
    }

    private static bool IsBlank(ReadOnlySpan<byte> line) => line.IndexOfAnyExcept((byte)' ', (byte)'\t') < 0;

    private static byte[] ReadAll(Stream input)
    {
        using var buffer = new MemoryStream();
        input.CopyTo(buffer);
        return buffer.ToArray();
    }
}

using Calc;

// Deeply nested expressions recurse once per level; run on a thread with a generous stack.
const int StackSize = 512 * 1024 * 1024;
var worker = new Thread(Run, StackSize);
worker.Start();
worker.Join();
return 0;

static void Run()
{
    using Stream input = Console.OpenStandardInput();
    using Stream output = Console.OpenStandardOutput();
    LineProcessor.Process(input, output);
}
